template <typename UnionPtrType>
OmniboxActionPtr OmniboxAction::Clone() const {
  switch (tag_) {
    case Tag::kFocusChange:
      return NewFocusChange(
          mojo::Clone(data_.focus_change));
    case Tag::kTextInput:
      return NewTextInput(
          mojo::Clone(data_.text_input));
    case Tag::kKey:
      return NewKey(
          mojo::Clone(data_.key));
    case Tag::kPointer:
      return NewPointer(
          mojo::Clone(data_.pointer));
    case Tag::kDropText:
      return NewDropText(
          mojo::Clone(data_.drop_text));
    case Tag::kDropFile:
      return NewDropFile(
          mojo::Clone(data_.drop_file));
    case Tag::kDragStart:
      return NewDragStart(
          mojo::Clone(data_.drag_start));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, OmniboxAction>::value>::type*>
bool OmniboxAction::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kFocusChange:
      return mojo::Equals(data_.focus_change, other.data_.focus_change);
    case Tag::kTextInput:
      return mojo::Equals(data_.text_input, other.data_.text_input);
    case Tag::kKey:
      return mojo::Equals(data_.key, other.data_.key);
    case Tag::kPointer:
      return mojo::Equals(data_.pointer, other.data_.pointer);
    case Tag::kDropText:
      return mojo::Equals(data_.drop_text, other.data_.drop_text);
    case Tag::kDropFile:
      return mojo::Equals(data_.drop_file, other.data_.drop_file);
    case Tag::kDragStart:
      return mojo::Equals(data_.drag_start, other.data_.drag_start);
  }

  return false;
}
